namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = [];
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            new(NextId(), "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)),
            new(NextId(), "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)),
            new(NextId(), "New feature available: dark mode.", DateTime.UtcNow.AddMinutes(-2)),
        ]);
    }

    /// <summary>Returns all notifications available at this moment.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    /// <summary>Returns only notifications created after the given ID.</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications.Where(n => n.Id > lastSeenId).ToList());
        }
    }

    /// <summary>
    /// Simulates an external system occasionally creating new notifications.
    /// Called by a background service so the polling page has something to find.
    /// </summary>
    public void TryAddRandom()
    {
        if (Random.Shared.Next(0, 3) != 0) return; // ~33% chance each tick

        string[] messages =
        [
            "Server health check passed.",
            "New comment on your post.",
            "Deployment completed successfully.",
            "Disk usage above 80%.",
            "A new user signed up.",
        ];

        lock (_lock)
        {
            _notifications.Add(new Notification(
                NextId(),
                messages[Random.Shared.Next(messages.Length)],
                DateTime.UtcNow));
        }
    }

    private int NextId() => _nextId++;
}

namespace NotificationsApp.Services;

/// <summary>
/// Periodically generates fake notifications so the polling page has new data to find.
/// </summary>
public class NotificationBackgroundService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(4), stoppingToken);
            notifications.TryAddRandom();
        }
    }
}

